"use client"

import * as React from "react"

import "./motion-accordion.css"

export type MotionAccordionProps = {
  title?: string
  children?: React.ReactNode
  className?: string
}

export function MotionAccordion({ title = "What changes when I swap kits?", children, className }: MotionAccordionProps) {
  const [open, setOpen] = React.useState(false)
  const panelId = React.useId()

  return (
    <div className={["kit-motion-accordion", className].filter(Boolean).join(" ")} data-open={open}>
      <button type="button" aria-expanded={open} aria-controls={panelId} onClick={() => setOpen((value) => !value)}>
        <span>{title}</span>
        <span aria-hidden="true">{open ? "−" : "+"}</span>
      </button>
      <div id={panelId} className="kit-motion-accordion__panel" hidden={!open}>
        <div className="kit-motion-accordion__content">
          {children ?? <p>Your product keeps its pages, content, and behavior. The selected kit changes the visual and interaction expression.</p>}
        </div>
      </div>
    </div>
  )
}

.kit-motion-accordion {
  width: min(100%, 520px);
  border: 1px solid var(--border);
  border-radius: var(--radius-card, 12px);
  background: var(--card);
  color: var(--card-foreground);
  box-shadow: var(--shadow-control, 0 1px 2px oklch(0 0 0 / 0.12));
  font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif);
}

.kit-motion-accordion > button {
  width: 100%;
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 750;
  text-align: left;
  cursor: pointer;
}

.kit-motion-accordion > button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.kit-motion-accordion__panel {
  border-top: 1px solid var(--border);
}

.kit-motion-accordion__content {
  padding: 14px 16px 16px;
  opacity: 1;
  transform: translateY(0);
  transition: opacity var(--kit-motion-duration, 180ms) var(--kit-motion-ease, cubic-bezier(0.23, 1, 0.32, 1)), transform var(--kit-motion-duration, 180ms) var(--kit-motion-ease, cubic-bezier(0.23, 1, 0.32, 1));
}

@starting-style {
  .kit-motion-accordion__content {
    opacity: 0;
    transform: translateY(calc(var(--kit-motion-distance-small, 4px) * -1));
  }
}

.kit-motion-accordion__content p {
  max-width: 52ch;
  margin: 0;
  color: var(--muted-foreground);
  line-height: 1.55;
}

.kit-motion-reduced .kit-motion-accordion__content {
  transform: none;
  transition: opacity 120ms linear;
}

@media (prefers-reduced-motion: reduce) {
  .kit-motion-accordion__content {
    transform: none;
    transition: opacity 120ms linear;
  }
}
